CREATE SCHEMA IF NOT EXISTS payroll_q6; SET search_path TO payroll_q6,public;
CREATE TABLE IF NOT EXISTS employees(employee_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,full_name TEXT NOT NULL,basic_salary NUMERIC(12,2) NOT NULL CHECK(basic_salary>=0),allowance NUMERIC(12,2) NOT NULL CHECK(allowance>=0),deduction NUMERIC(12,2) NOT NULL CHECK(deduction>=0),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS payroll(payroll_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id INT NOT NULL REFERENCES employees,pay_month DATE NOT NULL CHECK(EXTRACT(DAY FROM pay_month)=1),gross_pay NUMERIC(12,2) NOT NULL,net_pay NUMERIC(12,2) NOT NULL,UNIQUE(employee_id,pay_month));
CREATE TABLE IF NOT EXISTS salary_audit(audit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id INT NOT NULL REFERENCES employees,old_salary NUMERIC(12,2),new_salary NUMERIC(12,2),changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO employees VALUES(1,'Employee One',5000,500,300,true),(2,'Employee Two',6500,700,400,true),(3,'Employee Three',4000,200,250,false) ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION fn_net_pay(p_employee_id INT) RETURNS NUMERIC(12,2) LANGUAGE plpgsql AS $$
DECLARE b NUMERIC; a NUMERIC; d NUMERIC; n NUMERIC; BEGIN SELECT basic_salary,allowance,deduction INTO b,a,d FROM employees WHERE employee_id=p_employee_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown employee'; END IF; n:=b+a-d; IF n<0 THEN RAISE EXCEPTION 'Computed net pay is negative'; END IF; RETURN n; END $$;
CREATE OR REPLACE FUNCTION fn_salary_audit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF NEW.basic_salary IS DISTINCT FROM OLD.basic_salary THEN INSERT INTO salary_audit(employee_id,old_salary,new_salary) VALUES(NEW.employee_id,OLD.basic_salary,NEW.basic_salary); END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_salary_audit ON employees;
CREATE TRIGGER trg_salary_audit AFTER UPDATE ON employees FOR EACH ROW EXECUTE FUNCTION fn_salary_audit();
CREATE OR REPLACE PROCEDURE pr_process_payroll(p_month DATE) LANGUAGE plpgsql AS $$
DECLARE e RECORD; n NUMERIC(12,2); g NUMERIC(12,2); BEGIN IF p_month IS NULL OR EXTRACT(DAY FROM p_month)<>1 THEN RAISE EXCEPTION 'Pay month must be the first day of a month'; END IF; FOR e IN SELECT * FROM employees WHERE active LOOP g:=e.basic_salary+e.allowance; n:=fn_net_pay(e.employee_id); INSERT INTO payroll(employee_id,pay_month,gross_pay,net_pay) VALUES(e.employee_id,p_month,g,n) ON CONFLICT(employee_id,pay_month) DO NOTHING; END LOOP; END $$;
CALL pr_process_payroll(date_trunc('month',CURRENT_DATE)::date-interval '1 month');
CALL pr_process_payroll(date_trunc('month',CURRENT_DATE)::date);
CREATE OR REPLACE VIEW v_payroll_report AS SELECT e.full_name,p.pay_month,p.gross_pay,p.net_pay FROM payroll p JOIN employees e USING(employee_id);
CREATE INDEX IF NOT EXISTS ix_payroll_month ON payroll(pay_month);
EXPLAIN SELECT * FROM payroll WHERE pay_month=DATE '2026-10-01';
-- Schedule at 02:00 on day 1 monthly, passing the first day of previous month.
-- pgAgent/pg_cron command: CALL payroll_q6.pr_process_payroll((date_trunc('month',CURRENT_DATE)-interval '1 month')::date);
